mapper.select:
SELECT
FROM community_post p JOIN user u ON u.user_id = p.user_id JOIN series s ON s.series_id = p.series_id WHERE 1 = 1
AND p.post_id < #{lastId}
ORDER BY p.post_id DESC LIMIT #{size}

SELECT
FROM community_post p JOIN user u ON u.user_id = p.user_id JOIN series s ON s.series_id = p.series_id WHERE p.series_id IN (SELECT sa.series_id FROM useranimestatus uas JOIN series_anime sa ON sa.anime_id = uas.anime_id WHERE uas.user_id = #{userId} AND uas.status = #{status})
AND p.post_id < #{lastId}
ORDER BY p.post_id DESC LIMIT #{size}

SELECT , pl.periodCnt AS periodLikeCount FROM community_post p JOIN (SELECT post_id, COUNT(*) AS periodCnt FROM community_post_like WHERE created_at >= #{periodStart} GROUP BY post_id) pl ON pl.post_id = p.post_id JOIN user u ON u.user_id = p.user_id JOIN series s ON s.series_id = p.series_id WHERE 1 = 1
AND ( pl.periodCnt < #{lastValue} OR (pl.periodCnt = #{lastValue} AND p.post_id < #{lastId}) )
ORDER BY periodLikeCount DESC, p.post_id DESC LIMIT #{size}
